import * as THREE from 'three/webgpu';
import { gsap } from 'gsap';

/**
 * Stat tile for Home: a compact metric card (value + label) on a machined surface.
 * Loads a gear GLB mesh as the card visual, applies parallax-scroll cinematic primitive,
 * and attaches hover (rise-in) and click (emit:hub-home.select) interactions.
 */
export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // --- Scene placement ---
  const pos = config.scenePlacement.position;
  const rot = config.scenePlacement.rotation;
  const scl = config.scenePlacement.scale;
  group.position.set(pos.x, pos.y, pos.z);
  group.rotation.set(rot.x, rot.y, rot.z);
  group.scale.set(scl.x, scl.y, scl.z);

  // --- Load GLB mesh (cached) ---
  const gltf = ctx.glbLoader.get(config.meshUrl);
  if (gltf && gltf.scene) {
    const mesh = gltf.scene.clone();
    group.add(mesh);
  }

  // --- Apply cinematic primitives ---
  if (config.cinematicPrimitives) {
    for (const prim of config.cinematicPrimitives) {
      const fn = ctx.primitives[prim.name];
      if (fn) {
        fn(group, prim.params);
      }
    }
  }

  // --- Interaction handlers ---
  const handlers = {};
  let originalY = group.position.y; // used for hover revert
  if (config.interactions) {
    for (const interaction of config.interactions) {
      if (interaction.event === 'hover') {
        handlers.pointerover = () => {
          gsap.to(group.position, {
            y: originalY + 0.15,
            duration: 0.3,
            ease: 'power2.out',
          });
        };
        handlers.pointerout = () => {
          gsap.to(group.position, {
            y: originalY,
            duration: 0.3,
            ease: 'power2.out',
          });
        };
      } else if (interaction.event === 'click' && interaction.effect?.startsWith('emit:')) {
        const eventName = interaction.effect.replace('emit:', '');
        handlers.click = () => {
          group.dispatchEvent({ type: eventName });
          // Also call a global handler if available (optional)
          if (typeof ctx.onEmit === 'function') ctx.onEmit(eventName);
        };
      }
    }
  }
  group.userData.handlers = handlers;

  // --- Cleanup ---
  group.userData.cleanup = () => {
    gsap.killTweensOf(group.position);
    // Dispose loaded mesh resources
    group.traverse((child) => {
      if (child.isMesh) {
        child.geometry.dispose();
        if (Array.isArray(child.material)) {
          child.material.forEach((m) => m.dispose());
        } else if (child.material) {
          child.material.dispose();
        }
      }
    });
  };

  return group;
}
